steps.analogousExample:
/* Example: styling all direct children of a container */
.container > * {
  background-color: lightblue;
  padding: 10px;
  margin: 5px;
}

/* Example: style the first paragraph in a section */
section :first-child {
  background-color: lightblue;
}

/* Example: styling the last paragraph differently */
p:last-child {
  color: blue;
}

/* Example: styling even list items */
ul li:nth-child(even) {
  background-color: lightgray;
}

/* Example: styling the 5th child differently */
:nth-child(5) {
  color: red;
}

/* Select every 4th element starting from the 3rd */
.item:nth-child(4n+3) {
  background-color: lightgreen;
}

/* Example: style all paragraphs except those with 'hidden' class */
p:not(.hidden) {
  color: blue;
}

/* Example: Style odd elements except the first one */
li:nth-child(odd):not(:first-child) {
  color: red;
}
